// Flush-safe process exit: console.* writes to pipes (e.g. the Pterodactyl
// console) are ASYNCHRONOUS in Node — calling process.exit() immediately after
// can discard the message and look like a silent crash. This helper waits for
// the stream to drain (with a 200 ms backstop) before exiting.
function exitAfterFlush(code, msgs = [], stream = process.stderr) {
  const log = stream === process.stdout ? console.log : console.error;
  for (const m of msgs) log(m);
  const backstop = setTimeout(() => process.exit(code), 200);
  stream.write('', () => { clearTimeout(backstop); process.exit(code); });
}

const Database = (() => {
  try {
    return require('better-sqlite3');
  } catch (err) {
    exitAfterFlush(1, [
      '='.repeat(62),
      'FATAL: better-sqlite3 failed to load — native binding missing.',
      `  ${err && err.message ? err.message : err}`,
      'npm blocked its install script. Open the panel Console and run:',
      '  npm approve-scripts better-sqlite3',
      '  npm rebuild better-sqlite3',
      'Then press Start again.',
      '='.repeat(62),
    ]);
    // Halt module loading immediately (the scheduled exit fires within 200 ms).
    throw new Error('better-sqlite3 unavailable — see the message above.');
  }
})();

