const BOT_NAME = process.env.BOT_NAME || 'PteroBot';

function envBool(value, def) {
  if (value === undefined || value === null || value === '') return def;
  return ['1', 'true', 'yes', 'on'].includes(String(value).toLowerCase());
}

// --- secret cleaning ---------------------------------------------------------
// The #1 cause of "401 A valid API key is required" is NOT a wrong key — it is
// a key that was copy-pasted with invisible damage: wrapping quotes or
// backticks, a "Bearer " prefix, a line-wrap split, trailing whitespace, or
// zero-width characters from a website copy button.  This normalizer strips
// all of that BEFORE the key is ever used, and tells the console what it fixed.
function cleanEnvSecret(raw, label = 'secret') {
  const src = String(raw === undefined || raw === null ? '' : raw);
  let v = src;
  const fixes = [];
  // 1. invisible characters: BOM, zero-width, word-joiner, non-breaking space, CR
  const inv = v.replace(/[\uFEFF\u200B-\u200D\u2060\u00A0\r]/g, '');
  if (inv !== v) { fixes.push('invisible characters'); v = inv; }
  // 2. keys line-wrapped across multiple lines by a terminal / editor
  if (v.includes('\n')) { v = v.split('\n').map(s => s.trim()).filter(Boolean).join(''); fixes.push('line breaks'); }
  // 3. wrapping quotes / backticks on either side (any mix)
  const trimmed = v.trim();
  const unq = trimmed.replace(/^["'`]+/, '').replace(/["'`]+$/, '').trim();
  if (unq !== trimmed) { fixes.push('wrapping quotes'); }
  v = unq;
  if (v !== src && v === src.trim() && !fixes.length) fixes.push('whitespace');
  // 4. accidental "Bearer " prefix (copied from a curl example)
  if (/^bearer\s+/i.test(v)) { v = v.replace(/^bearer\s+/i, ''); fixes.push('\"Bearer \" prefix'); }
  // 5. repeated spaces collapsed (single spaces are flagged separately below)
  if (/\s{2,}/.test(v)) { v = v.replace(/\s+/g, ' '); fixes.push('repeated spaces'); }
  if (fixes.length) console.warn(`[config] ${label}: cleaned copy-paste artifacts (${fixes.join(', ')}).`);
  return v;
}

// Masked fingerprint of a secret — safe to print in the console, in /settings
// and in error embeds.  NEVER prints the full key.
function maskKey(key) {
  if (!key) return 'not set';
  const k = String(key);
  if (k.length <= 10) return `${k.slice(0, 2)}**** (${k.length} chars)`;
  return `${k.slice(0, 6)}…${k.slice(-4)} (${k.length} chars)`;
}

// Key sanity checks — catch "I pasted the wrong credential" at startup,
// long before the first /ai command fails with a cryptic 401.
function secretSanityWarnings() {
  const out = [];
  const k = config.naraApiKey;
  if (!k) return out;
  if (/^ptl[ac]_/.test(k)) out.push('NARA_API_KEY starts with ptlc_/ptla_ — that is a PTERODACTYL panel key, not a NaraRouter key. Create a key inside your NaraRouter account instead.');
  if (/^[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{15,}$/.test(k)) out.push('NARA_API_KEY looks like a DISCORD BOT TOKEN — remove it and paste your NaraRouter API key.');
  if (/\s/.test(k)) out.push('NARA_API_KEY contains a SPACE — the key was probably copied incompletely. Re-copy the full key and paste it as ONE line.');
  if (k.length < 16) out.push(`NARA_API_KEY is only ${k.length} characters — too short for a real key. Re-copy the FULL key.`);
  return out;
}

