// --- /update (v1.8.0 — the bot edits ITSELF via a separate editor AI key) ----

function selfEditRows(res) {
  const row = new ActionRowBuilder();
  const btn = (id, label, emoji, style) => new ButtonBuilder().setCustomId(id).setLabel(label).setEmoji(emoji).setStyle(style);
  if (res.kind === 'applied') {
    row.addComponents(
      btn('seupd:restart', 'Restart now', '🔄', ButtonStyle.Success),
      btn('seupd:undo', 'Undo (restore backup)', '↩️', ButtonStyle.Danger),
      btn('seupd:show', 'Show full edits', '📄', ButtonStyle.Secondary),
    );
  } else if (res.kind === 'preview') {
    row.addComponents(btn('seupd:show', 'Show full plan', '📄', ButtonStyle.Secondary));
  } else {
    row.addComponents(btn('seupd:show', 'Show what the AI tried', '📄', ButtonStyle.Secondary));
  }
  return [row];
}

function selfEditResultPayload(res, instruction) {
  const keyLine = res.ki
    ? `model \`${res.ki.model}\` • key \`${maskKey(res.ki.key)}\` — ${res.ki.dedicated ? '✅ dedicated **NARA_EDITOR_API_KEY** (separate from the chat AI)' : '⚠️ shared **main** NARA_API_KEY — set `NARA_EDITOR_API_KEY` in .env for a separate editor key'}`
    : 'editor key unknown';
  const editsValue = (res.editLines || []).map((l) => '• ' + l).join('\n').slice(0, 1000) || '—';
  if (res.kind === 'applied') {
    return {
      embeds: [embOk('🛠 Bot updated — restart to load it')
        .setDescription(truncate(`> ${instruction}`, 300))
        .addFields(
          { name: 'Editor AI', value: truncate(keyLine, 1000), inline: false },
          { name: 'What changed', value: truncate(String(res.summary), 1000), inline: false },
          { name: 'Edits applied', value: editsValue, inline: false },
          { name: 'Safety checks', value: '✅ `node --check` passed • ✅ structure intact • ✅ no duplicate commands', inline: false },
          { name: 'Backup', value: `\`${res.backup}\`\nUndo with the button below, or copy that file back manually.`, inline: false },
          { name: 'Next step', value: 'Press **Restart now** below — or restart on the panel. New/changed commands re-register automatically on boot (press Ctrl+R in Discord if the picker lags).', inline: false },
        )],
      components: selfEditRows(res),
    };
  }
  if (res.kind === 'preview') {
    return {
      embeds: [embInfo('🛠 Preview — nothing was written')
        .setDescription(truncate(`> ${instruction}`, 300))
        .addFields(
          { name: 'Editor AI', value: truncate(keyLine, 1000), inline: false },
          { name: 'Planned change', value: truncate(String(res.summary), 1000), inline: false },
          { name: 'Planned edits', value: editsValue, inline: false },
          { name: 'Checks', value: `✅ node --check passed • ✅ structure intact • ✅ ${res.commandNames.length} unique commands`, inline: false },
          { name: 'Apply it', value: 'Run the same `/update` again **without** `preview:true` and it will be written for real.', inline: false },
        )],
      components: selfEditRows(res),
    };
  }
  if (res.kind === 'failed-apply') {
    return {
      embeds: [embWarn('🛠 Plan rejected — nothing was written')
        .setDescription(truncate(`> ${instruction}`, 300))
        .addFields(
          { name: 'Editor AI', value: truncate(keyLine, 1000), inline: false },
          { name: 'What it wanted', value: truncate(String(res.summary), 800), inline: false },
          { name: 'Why it was blocked', value: truncate((res.errors || []).map((e) => '• ' + e).join('\n') || 'unknown', 1000), inline: false },
          ...(res.repairNote ? [{ name: 'Self-repair', value: truncate(String(res.repairNote).trim(), 500), inline: false }] : []),
          { name: 'What to do', value: 'The editor AI already got 2 automatic repair rounds with these exact errors. Try rephrasing (name the command exactly as it appears in /help), or press **Show what the AI tried** and apply the change by hand.', inline: false },
        )],
      components: selfEditRows(res),
    };
  }
  if (res.kind === 'failed-syntax') {
    return {
      embeds: [embErr('🛠 Syntax check failed — nothing was written')
        .setDescription(truncate(`> ${instruction}`, 300))
        .addFields(
          { name: 'Editor AI', value: truncate(keyLine, 1000), inline: false },
          { name: 'What it wanted', value: truncate(String(res.summary), 800), inline: false },
          { name: 'node --check says', value: truncate('```' + String(res.syntaxError || '').replace(/```/g, "'''") + '```', 1000), inline: false },
          ...(res.repairNote ? [{ name: 'Self-repair', value: truncate(String(res.repairNote).trim(), 500), inline: false }] : []),
        )],
      components: selfEditRows(res),
    };
  }
  if (res.kind === 'failed-write') {
    return {
      embeds: [embErr('🛠 Could not write the file')
        .setDescription(truncate(`> ${instruction}`, 300))
        .addFields(
          { name: 'Editor AI', value: truncate(keyLine, 1000), inline: false },
          { name: 'What it wanted', value: truncate(String(res.summary), 800), inline: false },
          { name: 'Write error', value: truncate(String(res.writeError || 'unknown'), 1000), inline: false },
          { name: 'Good news', value: 'The edit itself passed `node --check` and every safety check — only the disk write failed. Fix the permissions and run the same /update again.', inline: false },
        )],
      components: selfEditRows(res),
    };
  }
  // failed-sanity
  return {
    embeds: [embErr('🛠 Safety check failed — nothing was written')
      .setDescription(truncate(`> ${instruction}`, 300))
      .addFields(
        { name: 'Editor AI', value: truncate(keyLine, 1000), inline: false },
        { name: 'What it wanted', value: truncate(String(res.summary), 800), inline: false },
        { name: 'Problems', value: truncate((res.problems || []).map((p) => '• ' + p).join('\n') || 'unknown', 1000), inline: false },
        ...(res.repairNote ? [{ name: 'Self-repair', value: truncate(String(res.repairNote).trim(), 500), inline: false }] : []),
      )],
    components: selfEditRows(res),
  };
}

COMMANDS.push({
  data: new SlashCommandBuilder()
    .setName('update')
    .setDescription('AI-edits the bot itself — add / remove / change (admin only)')
    .addStringOption(o => o.setName('instruction')
      .setDescription('What should change? "add a /8ball command", "remove /8ball", "make /ping show the server name"')
      .setRequired(true)
      .setMaxLength(1500))
    .addStringOption(o => o.setName('action')
      .setDescription('Force the operation (default: auto-detect from the text)')
      .addChoices(
        { name: 'Auto — detect add / remove / change', value: 'auto' },
        { name: 'Add — create something new', value: 'add' },
        { name: 'Remove — delete a command / feature', value: 'remove' },
        { name: 'Change — modify an existing one', value: 'change' },
      ))
    .addBooleanOption(o => o.setName('preview')
      .setDescription('Plan only — show what WOULD change, write nothing (default: false)')),
  async execute(interaction) {
    if (!requireGuild(interaction)) return;
    if (!isAdmin(interaction.member)) {
      return replyError(interaction, 'Admin only', 'Only administrators can use /update — it rewrites the bot\'s own code.');
    }
    const ki = editorKeyInfo();
    if (!ki.key) {
      return replyError(interaction, 'No editor key', [
        'Set a NaraRouter key for /update in `.env`, then restart the bot:',
        '• `NARA_EDITOR_API_KEY=sk-…` — a **separate** key used ONLY for editing the bot (recommended)',
        '• or leave it empty to fall back to the main `NARA_API_KEY` (currently also unset)',
      ].join('\n'));
    }
    if (SELF_EDIT.busy) {
      return replyError(interaction, 'Editor busy', 'Another /update is still running — wait for its result first.');
    }
    const instruction = interaction.options.getString('instruction', true).trim();
    const preview = !!(interaction.options.getBoolean('preview') || false);
    const action = interaction.options.getString('action') || 'auto';
    SELF_EDIT.busy = true;
    await interaction.deferReply({ ephemeral: true });
    try {
      await interaction.editReply({
        embeds: [embInfo('🛠 Editor AI working…',
          `**Request:** ${truncate(instruction, 300)}\n**Mode:** ${action === 'auto' ? 'auto-detect' : action}\n\nLocating code → planning edits → syntax-checking → backup → write.\nIf a plan fails, the AI automatically gets 2 repair rounds with the exact errors — this can take a few minutes.`)],
      });
      const res = await runSelfUpdate(instruction, preview, action);
      await auditLog(interaction.client, interaction.user, 'selfupdate.' + res.kind, truncate(instruction, 200), {});
      return await interaction.editReply(selfEditResultPayload(res, instruction));
    } catch (err) {
      return interaction.editReply({ embeds: [embErr('Update failed', truncate(err && err.message ? err.message : String(err), 1500))] });
    } finally {
      SELF_EDIT.busy = false;
    }
  },
});

// --- /nodes (node status — wings reachability + capacity) ----------------------
const _nodesCache = { exp: 0, nodes: [] };
async function getAllNodesCached(force = false) {
  if (!force && Date.now() < _nodesCache.exp) return _nodesCache.nodes;
  const nodes = await pteroApp.listAllNodes();
  _nodesCache.nodes = nodes;
  _nodesCache.exp = Date.now() + 60000;
  return nodes;
}

// Direct wings (daemon) reachability probe: GET <scheme>://<fqdn>:<daemon_listen>/api/system
// is unauthenticated in Pterodactyl's wings and answers with its version + system
// info. Nodes behind a reverse proxy also get the public /_daemon/api/system path
// tried. First success wins; none -> unreachable (firewall/offline).
// NOTE: the FQDN is used ONLY for probing — it is never displayed anywhere.
function wingsCheck(node) {
  const base = `${node.scheme || 'https'}://${node.fqdn}`;
  const urls = [];
  if (node.daemon_listen) urls.push(`${base}:${node.daemon_listen}/api/system`);
  if (node.behind_proxy) urls.push(`${base}/_daemon/api/system`);
  if (!urls.length) return Promise.resolve({ online: null });
  return new Promise((resolve) => {
    let pending = urls.length;
    let settled = false;
    const finish = (v) => { if (!settled) { settled = true; resolve(v); } };
    const fail = () => { pending -= 1; if (pending === 0) finish({ online: false }); };
    for (const url of urls) {
      axios.get(url, { timeout: 2500, validateStatus: () => true })
        .then((res) => {
          if (res.status >= 200 && res.status < 300 && res.data) {
            finish({ online: true, version: res.data.version || null, system: res.data.system || null });
          } else {
            fail();
          }
        })
        .catch(fail);
    }
  });
}

function nodeAllocated(n) {
  const memAlloc = Number(n.allocated_mem ?? n.memory_allocated ?? n.allocated_ram ?? 0) * 1024 * 1024;
  const diskAlloc = Number(n.allocated_disk ?? n.disk_allocated ?? 0) * 1024 * 1024;
  return { memAlloc, diskAlloc };
}

function nodeCapacityLine(n) {
  const memTotal = (n.memory || 0) * 1024 * 1024;
  const diskTotal = (n.disk || 0) * 1024 * 1024;
  const { memAlloc, diskAlloc } = nodeAllocated(n);
  const pct = (used, total) => (total > 0 ? Math.min(100, Math.round((used / total) * 100)) : 0);
  const bar = (p) => '▰'.repeat(Math.round(p / 10)) + '▱'.repeat(10 - Math.round(p / 10));
  const mp = pct(memAlloc, memTotal);
  const dp = pct(diskAlloc, diskTotal);
  return `• RAM ${fmtBytes(memAlloc)} / ${fmtBytes(memTotal)} ${bar(mp)} ${mp}% • Disk ${fmtBytes(diskAlloc)} / ${fmtBytes(diskTotal)} ${bar(dp)} ${dp}%`;
}

async function nodesOverview(interaction) {
  await interaction.deferReply();
  // The full overview (nodes + wings probes) is cached for 30s — repeated
  // /nodes calls answer instantly instead of re-probing every daemon.
  if (_nodesOverviewCache.embed && Date.now() < _nodesOverviewCache.exp) {
    return interaction.editReply({ embeds: [_nodesOverviewCache.embed] });
  }
  let nodes;
  try { nodes = await getAllNodesCached(); } catch (err) {
    return interaction.editReply({ embeds: [embErr('Panel error', truncate(err.message, 500))] });
  }
  if (!nodes.length) return interaction.editReply({ embeds: [embInfo('🖥 Node status', 'The panel has no nodes configured.')] });
  const checks = await Promise.all(nodes.map(n => wingsCheck(n)));
  const lines = nodes.slice(0, 20).map((n, i) => {
    const c = checks[i];
    const dot = c.online === true ? '🟢' : (c.online === false ? '🔴' : '⚪');
    const state = c.online === true
      ? `online${c.version ? ` — wings v${truncate(String(c.version), 24)}` : ''}`
      : (c.online === false ? 'unreachable' : 'unknown');
    const maint = n.maintenance_mode ? ' • 🛠️ **maintenance**' : '';
    return `${dot} **${truncate(n.name, 60)}** — ${state}${maint}\n${nodeCapacityLine(n)}`;
  });
  if (nodes.length > 20) lines.push(`…and ${nodes.length - 20} more — use \`/nodes node:<id>\` (staff) for details.`);
  const embed = embInfo('🖥 Node status')
    .setDescription(lines.join('\n'))
    .setFooter({ text: 'Reachability is probed directly on the wings daemon • "allocated" = reserved by servers' });
  _nodesOverviewCache.embed = embed;
  _nodesOverviewCache.exp = Date.now() + 30000;
  return interaction.editReply({ embeds: [embed] });
}

const _nodesOverviewCache = { exp: 0, embed: null };

async function nodesDetail(interaction, id) {
  await interaction.deferReply();
  let n;
  try { n = await pteroApp.getNode(id, 'servers'); } catch (err) {
    return interaction.editReply({ embeds: [embErr('Node not found', truncate(err.message, 500))] });
  }
  const c = await wingsCheck(n);
  const serverCount = n.relationships && n.relationships.servers && Array.isArray(n.relationships.servers.data)
    ? n.relationships.servers.data.length : null;
  const { memAlloc, diskAlloc } = nodeAllocated(n);
  const embed = embInfo(`🖥 Node — ${n.name}`)
    .addFields(
      { name: 'ID', value: String(n.id), inline: true },
      { name: 'Location', value: String(n.location_id || '—'), inline: true },
      { name: 'Servers', value: serverCount === null ? '—' : String(serverCount), inline: true },
      { name: 'Status', value: `${c.online === true ? `🟢 online${c.version ? ` (wings v${truncate(String(c.version), 24)})` : ''}` : c.online === false ? '🔴 unreachable' : '⚪ unknown'}${n.maintenance_mode ? ' • 🛠️ maintenance' : ''}`, inline: false },
      { name: 'Memory', value: `${fmtBytes((n.memory || 0) * 1024 * 1024)} total • ${fmtBytes(memAlloc)} allocated • ${n.memory_overallocate ?? 0}% overallocate`, inline: true },
      { name: 'Disk', value: `${fmtBytes((n.disk || 0) * 1024 * 1024)} total • ${fmtBytes(diskAlloc)} allocated • ${n.disk_overallocate ?? 0}% overallocate`, inline: true },
      { name: 'Upload size', value: fmtBytes((n.upload_size || 0) * 1024 * 1024), inline: true },
    );
  return interaction.editReply({ embeds: [embed] });
}

COMMANDS.push({
  data: new SlashCommandBuilder()
    .setName('nodes')
    .setDescription('Panel node status — online state, RAM & disk capacity')
    .addIntegerOption(o => o.setName('node').setDescription('Detailed view for one node (staff only)').setMinValue(1).setAutocomplete(true)),
  async autocomplete(interaction) {
    const focused = String(interaction.options.getFocused() || '').toLowerCase();
    let nodes = [];
    try { nodes = await getAllNodesCached(); } catch { nodes = []; }
    const opts = nodes
      .map(n => ({ name: truncate(`${n.name} (#${n.id})`, 100), value: Number(n.id) }))
      .filter(o => !focused || o.name.toLowerCase().includes(focused))
      .slice(0, 25);
    try { return await interaction.respond(opts); } catch { /* autocomplete expired */ }
  },
  async execute(interaction) {
    if (!requireGuild(interaction)) return;
    if (!pteroApp.configured) {
      return replyError(interaction, 'Not configured', 'The Application API is not configured — set PTERODACTYL_URL and PTERODACTYL_APPLICATION_KEY in .env.');
    }
    const nodeRef = interaction.options.getInteger('node');
    if (nodeRef) {
      if (!isStaff(interaction.member)) return replyError(interaction, 'Staff only', 'Detailed node information is staff-only — use `/nodes` for the public overview.');
      return nodesDetail(interaction, nodeRef);
    }
    return nodesOverview(interaction);
  },
});

