// --- /link (self-link your Pterodactyl account) ------------------------------
COMMANDS.push({
  data: new SlashCommandBuilder()
    .setName('link')
    .setDescription('Link your Discord account to your Pterodactyl account (for /server-create)')
    .addIntegerOption(o => o.setName('ptero_id').setDescription('Your Pterodactyl user ID (panel Settings page)').setRequired(true).setMinValue(1))
    .addStringOption(o => o.setName('email').setDescription('Your Pterodactyl account email').setRequired(true)),
  async execute(interaction) {
    if (!requireGuild(interaction)) return;
    const pteroId = interaction.options.getInteger('ptero_id', true);
    const email = interaction.options.getString('email', true).trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return replyError(interaction, 'Invalid email', 'That does not look like a valid email address.');
    let username = null;
    let verified = false;
    if (pteroApp.configured) {
      try {
        const u = await pteroApp.getUser(pteroId);
        username = u.username || null;
        verified = true;
        if (String(u.email).toLowerCase() !== email) {
          return replyError(interaction, 'Email mismatch', `That Pterodactyl ID belongs to \`${u.email}\`, not \`${email}\`. Use the account's real email.`);
        }
      } catch (err) {
        if (err && err.status === 404) return replyError(interaction, 'Not found', `No Pterodactyl user with ID ${pteroId} exists on the panel.`);
      }
    }
    linkAccount({ discordId: interaction.user.id, pteroUserId: pteroId, email, username, linkedBy: interaction.user.id });
    await auditLog(interaction.client, interaction.user, 'account.link', email, { pteroId });
    return interaction.reply({
      embeds: [embOk('Account linked', `Your Discord account is now linked to Pterodactyl user **${username || email}** (ID ${pteroId}).${pteroApp.configured ? '' : '\n⚠️ Application API not configured — could not verify against the panel.'}${verified ? '' : ''}`)],
    });
  },
});

