  full: ['control.start', 'control.stop', 'control.restart', 'control.kill', 'control.command', 'control.console', 'control.install',
    'file.read', 'file.read-content', 'file.write', 'file.create', 'file.delete', 'file.archive',
    'startup.read', 'startup.update', 'database.read', 'database.create', 'database.delete', 'database.update',
    'schedule.read', 'schedule.create', 'schedule.update', 'schedule.delete',
    'backup.read', 'backup.create', 'backup.delete', 'backup.restore',
    'allocation.read', 'allocation.create', 'allocation.update', 'allocation.delete',
    'network.read', 'settings.rename', 'settings.reinstall', 'activity.read'],
  power: ['control.start', 'control.stop', 'control.restart', 'control.kill', 'control.console', 'control.command'],
  files: ['file.read', 'file.read-content', 'file.write', 'file.create', 'file.delete', 'file.archive', 'control.console'],
  backups: ['backup.read', 'backup.create', 'backup.delete', 'backup.restore', 'file.read', 'file.read-content', 'control.start', 'control.stop', 'control.restart'],
