// Shared creation step for BOTH flows (simple: specs -> name; advanced: review
// -> Create server). Uses the Application API, audits, and auto-grants the
// owner access so they can manage the new server immediately.
async function wizCreateNow(interaction, sid, d) {
  await interaction.deferUpdate();
  try {
    const payload = wizBuildPayload(d);
    const created = await pteroApp.createServer(payload);
    wizSessions.delete(sid);
    await auditLog(interaction.client, interaction.user, 'admin.server_create', created.identifier, {
      name: d.name, owner: d.user.email, egg: d.egg.name, node: d.node.name,
    });
    // Auto-grant the owner access to the new server so they can manage it immediately.
    let accessNote;
    const ownerAccount = getAccountByPteroId(d.user.id);
    if (ownerAccount) {
      if (!hasServerAccess(ownerAccount.discord_id, created.identifier)) {
        grantServerAccess(ownerAccount.discord_id, created.identifier, 'auto');
      }
      accessNote = `<@${ownerAccount.discord_id}> can manage it immediately with \`/server\` commands.`;
    } else {
      accessNote = 'The owner is not linked to a Discord user yet — they will be auto-linked by username the first time they use the bot.';
    }
    // Optional auto-suspend schedule chosen in the wizard.
    let suspendNote = 'never (no auto-suspend scheduled)';
    if (d.autoSuspendMs && d.autoSuspendMs >= 60000) {
      try {
        autoSuspendSet({ serverId: created.id, identifier: created.identifier, name: created.name, ms: d.autoSuspendMs, createdBy: interaction.user.id });
        suspendNote = `in **${fmtDuration(d.autoSuspendMs)}** (<t:${Math.floor((Date.now() + d.autoSuspendMs) / 1000)}:R>)`;
        await auditLog(interaction.client, interaction.user, 'server.auto_suspend_set', created.identifier, { in: fmtDuration(d.autoSuspendMs), via: 'wizard' });
      } catch { /* scheduling failed — server still created */ }
    }
    return interaction.editReply({
      embeds: [embOk('Server created 🎉')
        .setDescription(`**${created.name}** is ready.`)
        .addFields(
          { name: 'Identifier', value: `\`${created.identifier}\``, inline: true },
          { name: 'Internal ID', value: String(created.id), inline: true },
          { name: 'Owner', value: d.user.email, inline: true },
          ...(d.mcVersion ? [{ name: 'Minecraft version', value: `**${d.mcVersion}** (set at creation)`, inline: true }] : []),
          { name: 'Limits', value: `${fmtMb(d.limits.memory)} RAM • ${fmtMb(d.limits.disk)} disk • ${d.limits.cpu}% CPU • ${d.limits.databases} db • ${d.limits.backups} backups`, inline: false },
          { name: 'Auto-suspend', value: suspendNote, inline: false },
          { name: 'Access', value: accessNote, inline: false },
        )],
      components: [],
    });
  } catch (err) {
    return interaction.editReply({ embeds: [embErr('Creation failed', truncate(err.message, 1000))], components: [] });
  }
}

