// 13.5 UTILITY SUITE — 274 real tools via 6 hub commands (convert hub removed in v1.7.0)
// 13.5 UTILITY SUITE — /text /fun /util /time /color /mc hub commands.
// Discord caps top-level
// commands at 100, so the suite is delivered as hubs whose subcommand groups
// hold the individual tools. Every tool has REAL functionality.
// ---------------------------------------------------------------------------
// ---- tiny self-contained helpers (no deps outside Node stdlib) -------------
function sTrunc(s, n) {
  const str = String(s === null || s === undefined ? '' : s);
  return str.length > n ? str.slice(0, Math.max(0, n - 1)) + '…' : str;
}
function fmtSuiteNum(x) {
  if (x === null || x === undefined || Number.isNaN(x)) return '?';
  if (!Number.isFinite(x)) return x > 0 ? '∞' : '-∞';
  const a = Math.abs(x);
  if (a !== 0 && (a >= 1e15 || a < 1e-7)) return x.toExponential(6);
  const r = Math.round(x * 1e8) / 1e8;
  return r.toLocaleString('en-US', { maximumFractionDigits: 8 });
}
function suiteArg(interaction, name, fallback) {
  try {
    const v = interaction.options.get(name);
    return v === null || v === undefined ? fallback : v.value;
  } catch { return fallback; }
}
function suiteStr(interaction, name, fallback = '') {
  const v = suiteArg(interaction, name, undefined);
  return v === undefined || v === null ? fallback : String(v);
}
function suiteNum(interaction, name, fallback = NaN) {
  const v = suiteArg(interaction, name, undefined);
  return v === undefined || v === null || v === '' ? fallback : Number(v);
}

