// --- v1.6.0 deterministic fun meters (pure — used by /fun rates + /ship etc.) ---
// Stable per-user percentages: the SAME user always gets the SAME score (seeded
// FNV-1a over the salt + user ids), so /gayness is not random spam — it is a
// "personality scan" with a fixed verdict, like every classic Discord fun bot.
function hashPercent(salt, ...parts) {
  const s = `${String(salt)}|${parts.map(p => String(p)).sort().join('|')}`;
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h % 101; // 0..100
}
function meterBar(p, len = 10) {
  const pct = Math.max(0, Math.min(100, Number(p) || 0));
  const n = Math.max(0, Math.min(len, Math.round((pct / 100) * len)));
  return '▰'.repeat(n) + '▱'.repeat(len - n);
}
function shipName(a, b) {
  const clean = (s) => String(s || 'user').replace(/[^A-Za-z0-9]/g, '') || 'user';
  const x = clean(a), y = clean(b);
  const head = x.slice(0, Math.max(1, Math.ceil(x.length / 2)));
  const tail = y.slice(Math.floor(y.length / 2)) || y;
  return (head + tail).toLowerCase();
}
function verdictFor(pct, tiers) {
  let out = tiers[0][1];
  for (const [min, text] of tiers) if (pct >= min) out = text;
  return out;
}

