// RPS game logic (used by the button handler in the glue section)
const RPS_MOVES = { rock: '🪨 Rock', paper: '📄 Paper', scissors: '✂️ Scissors' };
const RPSLS_MOVES = { rock: '🪨 Rock', paper: '📄 Paper', scissors: '✂️ Scissors', lizard: '🦎 Lizard', spock: '🖖 Spock' };
const RPS_BEATS = {
  rock: ['scissors', 'lizard'], paper: ['rock', 'spock'], scissors: ['paper', 'lizard'],
  lizard: ['spock', 'paper'], spock: ['scissors', 'rock'],
};
function rpsOutcome(userMove, botMove) {
  if (userMove === botMove) return { verdict: 'tie', text: "It's a tie! Try again." };
  const userWins = (RPS_BEATS[userMove] || []).includes(botMove);
  const why = { rock: { scissors: 'rock crushes scissors', lizard: 'rock crushes lizard' }, paper: { rock: 'paper covers rock', spock: 'paper disproves Spock' }, scissors: { paper: 'scissors cuts paper', lizard: 'scissors decapitates lizard' }, lizard: { spock: 'lizard poisons Spock', paper: 'lizard eats paper' }, spock: { scissors: 'Spock smashes scissors', rock: 'Spock vaporizes rock' } };
  const reason = (why[userMove] && why[userMove][botMove]) || (why[botMove] && why[botMove][userMove]) || '';
  return userWins
    ? { verdict: 'win', text: `You win — ${reason}! 🎉` }
    : { verdict: 'lose', text: `I win — ${reason}! 🤖` };
}

// ============================================================================
// 16.5 /util — info, polls, reminders, misc
// ============================================================================
function parseEmojiRef(raw) {
  const m = /^<(a)?:([A-Za-z0-9_~]+):(\d+)>$/.exec(String(raw || '').trim());
  if (m) return { animated: m[1] === 'a', name: m[2], id: m[3] };
  const uni = /^\p{Extended_Pictographic}$/u.exec(String(raw || '').trim());
  if (uni) return { unicode: String(raw).trim() };
  return null;
}
function emojiUrl(ref) { return `https://cdn.discordapp.com/emojis/${ref.id}.${ref.animated ? 'gif' : 'png'}?size=256`; }
function snowflakeToDate(id) { return new Date(Number(BigInt(id) >> 22n) + 1420070400000); }

