function colorName(hex) {
  const target = hex.replace('#', '').toUpperCase();
  const direct = Object.entries(CSS_COLORS).find(([, v]) => v.replace('#', '') === target);
  if (direct) return direct[0];
  const { r, g, b } = hexToRgb(hex);
  let best = 'custom', bestD = Infinity;
  for (const [name, v] of Object.entries(CSS_COLORS)) {
    const c = hexToRgb(v);
    const d = (c.r - r) ** 2 + (c.g - g) ** 2 + (c.b - b) ** 2;
    if (d < bestD) { bestD = d; best = name; }
  }
  return bestD <= 900 ? `closest: ${best}` : 'custom shade';
}
