async function mcUuid(nameOrUuid) {
  const raw = String(nameOrUuid || '').trim();
  if (/^[0-9a-f]{32}$/i.test(raw.replace(/-/g, ''))) return { id: raw.replace(/-/g, '').toLowerCase(), name: raw };
  const res = await axios.get(`https://api.mojang.com/users/profiles/minecraft/${encodeURIComponent(raw)}`, { timeout: 10000, validateStatus: () => true });
  if (res.status === 200 && res.data && res.data.id) return { id: res.data.id, name: res.data.name };
  if (res.status === 204 || res.status === 404) throw new Error(`No Minecraft account named "${raw}" exists.`);
  throw new Error(`Mojang API error (HTTP ${res.status}).`);
}
