// ---- suite-wide helpers -------------------------------------------------------
function suiteEndpointCount() {
  let n = 0;
  for (const hub of Object.values(SUITE_HUBS)) {
    for (const g of hub.groups || []) n += g.tools.length;
    n += (hub.subs || []).length;
  }
  return n;
}
function suiteFindTool(hubKey, group, sub) {
  const hub = SUITE_HUBS[hubKey];
  if (!hub) return null;
  if (group) {
    const g = (hub.groups || []).find(x => x.key === group);
    if (!g) return null;
    return g.tools.find(t => t.key === sub) || null;
  }
  const direct = (hub.subs || []).find(t => t.key === sub) || null;
  if (direct) return direct;
  // Split hubs expose a synthetic `tools` index subcommand on their base command.
  if (sub === 'tools' && typeof SUITE_SPLIT_HUBS !== 'undefined' && SUITE_SPLIT_HUBS.has(hubKey)) {
    return suiteToolsIndexTool(hubKey);
  }
  return null;
}

// >>> SUITE-GLUE-START
// (This block is appended AFTER the pure block inside index.js — it uses
// discord.js, COMMANDS, componentHandlers, embInfo, replyError from the host.)

const SUITE_BRAND_SUFFIX = 'utility suite';

// ---- suite option type helpers -----------------------------------------------
function suiteOpt(o) {
  return (opt) => {
    opt.setName(o.name).setDescription(truncate(o.desc || o.name, 100)).setRequired(!!o.req);
    // Autocomplete-backed options (units, CSS color names) — Discord only
    // sends autocomplete interactions for options flagged here.
    if (o.auto) opt.setAutocomplete(true);
    if ((o.type === 'integer') && o.min === undefined) opt.setMinValue(-2147483648).setMaxValue(2147483647);
    if (o.type === 'number') opt.setMinValue(-1e12).setMaxValue(1e12);
    return opt;
  };
}
const SUITE_OPT_BUILDERS = {
  string: (b, o) => b.addStringOption(suiteOpt(o)),
  integer: (b, o) => b.addIntegerOption(suiteOpt(o)),
  number: (b, o) => b.addNumberOption(suiteOpt(o)),
  boolean: (b, o) => b.addBooleanOption(suiteOpt(o)),
  user: (b, o) => b.addUserOption(suiteOpt(o)),
  role: (b, o) => b.addRoleOption(suiteOpt(o)),
  channel: (b, o) => b.addChannelOption(suiteOpt(o)),
};

// ---- hub command builders ------------------------------------------------------
// Discord limits: 100 top-level commands, 25 options per command/group,
// max nesting /hub group sub. Every hub below respects those caps.
function buildSuiteHubCommand(hub) {
  const builder = new SlashCommandBuilder()
    .setName(hub.name)
    .setDescription(truncate(hub.desc, 100));
  for (const g of (hub.groups || [])) {
    if (g.tools.length > 25) throw new Error(`Group /${hub.name} ${g.key} has ${g.tools.length} tools (max 25).`);
    builder.addSubcommandGroup(gg => {
      gg.setName(g.key).setDescription(truncate(g.desc, 100));
      for (const tool of g.tools) {
        gg.addSubcommand(sc => {
          sc.setName(tool.key).setDescription(truncate(tool.desc, 100));
          for (const o of tool.opts || []) {
            const add = SUITE_OPT_BUILDERS[o.type || 'string'];
            if (add) add(sc, o);
          }
          return sc;
        });
      }
      return gg;
    });
  }
  for (const sub of hub.subs || []) {
    builder.addSubcommand(sc => {
      sc.setName(sub.key).setDescription(truncate(sub.desc, 100));
      for (const o of sub.opts || []) {
        const add = SUITE_OPT_BUILDERS[o.type || 'string'];
        if (add) add(sc, o);
      }
      return sc;
    });
  }
  const topOptions = (hub.groups || []).length + (hub.subs || []).length;
  if (topOptions > 25) throw new Error(`Hub /${hub.name} has ${topOptions} top-level options (max 25).`);
  return builder;
}

// ---- suite result renderer -------------------------------------------------------
function suiteSend(interaction, payload) {
  const embed = embInfo(payload.title || 'Result')
    .setDescription(payload.desc || '\u200b');
  if (payload.fields && payload.fields.length) {
    for (const f of payload.fields) {
      if (f && f.name && f.value !== undefined && f.value !== null && f.value !== '') {
        embed.addFields({ name: truncate(String(f.name), 250), value: truncate(String(f.value), 1000), inline: f.inline !== false });
      }
    }
  }
  if (payload.input !== undefined) {
    embed.addFields({ name: 'Input', value: truncate(String(payload.input), 1000), inline: false });
  }
  if (payload.result !== undefined) {
    embed.addFields({ name: 'Result', value: truncate(String(payload.result), 1000), inline: false });
  }
  if (payload.thumb) embed.setThumbnail(payload.thumb);
  if (payload.image) embed.setImage(payload.image);
  embed.setFooter({ text: `${BOT_NAME} • ${SUITE_BRAND_SUFFIX} • v${VERSION}` });
  embed.setTimestamp();
  return interaction.deferred
    ? interaction.editReply({ embeds: [embed] })
    : interaction.reply({ embeds: [embed] });
}

// ---- suite dispatcher (slash) ------------------------------------------------------
const SUITE_GAMES = new Map();       // guess-game nonce -> state
const SUITE_GAME_NOUNCES = new Map(); // rps/rpsls nonce -> state

async function runSuiteCommand(interaction) {
  // Split hubs register ONE COMMAND PER GROUP (e.g. /text-case); the
  // route map points every command back at its hub (+ fixed group), so the
  // dispatcher and all tool implementations stay unchanged.
  const route = (typeof SUITE_CMD_ROUTES !== 'undefined' && SUITE_CMD_ROUTES[interaction.commandName]) || { hub: interaction.commandName };
  const hubKey = route.hub;
  const group = interaction.options.getSubcommandGroup(false) || route.group || null;
  const sub = interaction.options.getSubcommand(false);
  const tool = suiteFindTool(hubKey, group, sub);
  if (!tool) {
    return replyError(interaction, 'Unknown tool', `/${hubKey} ${group || ''} ${sub || ''} does not match any tool.`);
  }
  // Anything async (mc APIs, reminders, polls, userinfo fetches) gets deferred.
  const isAsync = tool.run && tool.run.constructor && tool.run.constructor.name === 'AsyncFunction';
  const mustDefer = isAsync || hubKey === 'mc' || hubKey === 'util';
  if (mustDefer && !interaction.deferred) {
    await interaction.deferReply().catch(() => {});
  }
  try {
    const payload = await tool.run(interaction);
    if (!payload) throw new Error('The tool returned nothing.');
    if (payload.__game) {
      const nonce = crypto.randomBytes(4).toString('hex');
      let embed, rows;
      if (payload.__game === 'rps' || payload.__game === 'rpsls') {
        const rpsls = payload.__game === 'rpsls';
        const moves = rpsls ? RPSLS_MOVES : RPS_MOVES;
        const emojis = { rock: '🪨', paper: '📄', scissors: '✂️', lizard: '🦎', spock: '🖖' };
        embed = embInfo(rpsls ? 'Rock Paper Scissors Lizard Spock' : 'Rock Paper Scissors')
          .setDescription(rpsls ? 'Five moves. Lizard poisons Spock, Spock smashes scissors… you know the rest.' : 'Pick your move — best of luck!');
        rows = [new ActionRowBuilder().addComponents(
          ...Object.keys(moves).map(m => new ButtonBuilder()
            .setCustomId(`sgame:${nonce}:${m}`)
            .setLabel(m[0].toUpperCase() + m.slice(1))
            .setEmoji(emojis[m])
            .setStyle(ButtonStyle.Primary)),
        )];
        SUITE_GAME_NOUNCES.set(nonce, { kind: payload.__game, userId: interaction.user.id, ts: Date.now() });
      } else if (payload.__game === 'guess') {
        const secret = 1 + Math.floor(Math.random() * 100);
        embed = embInfo('Guess my number — 1 to 100')
          .setDescription('I picked a number between **1 and 100**.\nClick the block that contains it — I will tell you if you are getting closer by narrowing the range!');
        rows = [new ActionRowBuilder().addComponents(
          new ButtonBuilder().setCustomId(`sguess:${nonce}:1-25`).setLabel('1–25').setStyle(ButtonStyle.Secondary),
          new ButtonBuilder().setCustomId(`sguess:${nonce}:26-50`).setLabel('26–50').setStyle(ButtonStyle.Secondary),
          new ButtonBuilder().setCustomId(`sguess:${nonce}:51-75`).setLabel('51–75').setStyle(ButtonStyle.Secondary),
          new ButtonBuilder().setCustomId(`sguess:${nonce}:76-100`).setLabel('76–100').setStyle(ButtonStyle.Secondary),
        )];
        SUITE_GAMES.set(nonce, { userId: interaction.user.id, secret, low: 1, high: 100, rounds: 0, ts: Date.now() });
      } else {
        throw new Error('Unknown game.');
      }
      return interaction.deferred
        ? interaction.editReply({ embeds: [embed], components: rows })
        : interaction.reply({ embeds: [embed], components: rows });
    }
    return suiteSend(interaction, payload);
  } catch (err) {
    if (interaction.deferred) {
      return interaction.editReply({ embeds: [embErr('Tool failed', truncate(err.message, 900))] });
    }
    return replyError(interaction, 'Tool failed', err.message);
  }
}

// ---- RPS buttons (sgame:<nonce>:<move>) ------------------------------------------
componentHandlers.set('sgame', async (interaction, parts) => {
  const [nonce, move] = parts;
  const game = SUITE_GAME_NOUNCES.get(nonce);
  if (!game) return replyError(interaction, 'Expired', 'This game has expired — start a new one.');
  if (game.userId !== interaction.user.id) return replyError(interaction, 'Not yours', 'Only the player who started this game can play it.');
  SUITE_GAME_NOUNCES.delete(nonce);
  const moves = game.kind === 'rpsls' ? RPSLS_MOVES : RPS_MOVES;
  if (!moves[move]) return replyError(interaction, 'Invalid', 'Unknown move.');
  const botMove = pick(Object.keys(moves));
  const outcome = rpsOutcome(move, botMove);
  const color = outcome.verdict === 'win' ? COLORS.ok : outcome.verdict === 'lose' ? COLORS.err : COLORS.warn;
  const embed = new EmbedBuilder()
    .setColor(color)
    .setTitle(game.kind === 'rpsls' ? 'RPSLS — result' : 'Rock Paper Scissors — result')
    .setDescription(`You picked **${moves[move]}**\nI picked **${moves[botMove]}**\n\n${outcome.text}`)
    .setFooter({ text: `${BOT_NAME} • ${SUITE_BRAND_SUFFIX}` });
  return interaction.update({ embeds: [embed], components: [] });
});

// ---- number-guess buttons (sguess:<nonce>:<lo>-<hi>) — unified handler -----------
componentHandlers.set('sguess', async (interaction, parts) => {
  const [nonce, key] = parts;
  const g = SUITE_GAMES.get(nonce);
  if (!g) return replyError(interaction, 'Expired', 'This game has expired — start a new one.');
  if (g.userId !== interaction.user.id) return replyError(interaction, 'Not yours', 'Only the player who started this game can play it.');
  const m = /^(\d+)-(\d+)$/.exec(String(key || ''));
  if (!m) return replyError(interaction, 'Invalid', 'Unknown guess button.');
  const lo = Number(m[1]), hi = Number(m[2]);
  if (lo !== Math.max(g.low, lo)) { /* clamp below */ }
  const inRange = g.secret >= lo && g.secret <= hi;
  g.rounds += 1;
  if (lo === hi) {
    // Exact single-number guess.
    SUITE_GAMES.delete(nonce);
    const embed = (inRange ? embOk('Guessed it! 🎉') : embWarn('So close!'))
      .setDescription(`My number was **${g.secret}**.\nFinished in ${g.rounds} rounds.`)
      .setFooter({ text: `${BOT_NAME} • ${SUITE_BRAND_SUFFIX}` });
    return interaction.update({ embeds: [embed], components: [] });
  }
  if (inRange) { g.low = lo; g.high = hi; }
  else if (hi < g.secret) g.low = Math.max(g.low, hi + 1);
  else g.high = Math.min(g.high, lo - 1);
  if (g.low >= g.high) {
    SUITE_GAMES.delete(nonce);
    const embed = embOk('Nailed it! 🎉')
      .setDescription(`My number was **${g.secret}**.\nFinished in ${g.rounds} rounds.`)
      .setFooter({ text: `${BOT_NAME} • ${SUITE_BRAND_SUFFIX}` });
    return interaction.update({ embeds: [embed], components: [] });
  }
  // Build the next set of range buttons for the narrowed window.
  const span = g.high - g.low + 1;
  const blocks = Math.max(1, Math.min(4, Math.ceil(span / 25)));
  const step = Math.ceil(span / blocks);
  const row = new ActionRowBuilder();
  for (let i = 0; i < blocks; i++) {
    const blo = g.low + i * step;
    const bhi = Math.min(g.high, blo + step - 1);
    if (blo > bhi) break;
    row.addComponents(new ButtonBuilder()
      .setCustomId(`sguess:${nonce}:${blo}-${bhi}`)
      .setLabel(`${blo}–${bhi}`)
      .setStyle(ButtonStyle.Secondary));
  }
  const embed = embInfo(`Guess my number — ${g.low} to ${g.high}`)
    .setDescription(`Range narrowed to **${g.low}–${g.high}**.\nRound ${g.rounds + 1} — which block hides my number?`)
    .setFooter({ text: `${BOT_NAME} • ${SUITE_BRAND_SUFFIX}` });
  return interaction.update({ embeds: [embed], components: [row] });
});

// ---- color / timezone autocomplete -----------------------------------------------
async function suiteAutocomplete(interaction) {
  const focused = interaction.options.getFocused(true);
  const q = String(focused.value || '').toLowerCase().trim();
  let choices = [];
  if (focused.name === 'color' || focused.name === 'a' || focused.name === 'b') {
    choices = Object.entries(CSS_COLORS).map(([n, v]) => ({ name: truncate(`${n} ${v}`, 100), value: v }))
      .filter(c => !q || c.name.toLowerCase().includes(q))
      .slice(0, 25);
  } else if (focused.name === 'zone' || focused.name === 'zone-a' || focused.name === 'zone-b') {
    choices = TZ_CHOICES.map(z => ({ name: z, value: z }))
      .filter(c => !q || c.name.toLowerCase().includes(q))
      .slice(0, 25);
  }
  return interaction.respond(choices).catch(() => {});
}

// ---- reminder scheduler ------------------------------------------------------------
let suiteReminderTimer = null;
function startSuiteReminders(client) {
  if (suiteReminderTimer) clearInterval(suiteReminderTimer);
  suiteReminderTimer = setInterval(async () => {
    try {
      const due = suiteDueReminders();
      for (const r of due) {
        try {
          const text = `⏰ **Reminder**\n> ${sTrunc(r.text, 400)}`;
          if (r.dm) {
            const user = await client.users.fetch(r.user_id).catch(() => null);
            if (user) await user.send(text).catch(() => {});
          } else if (r.channel_id) {
            const chan = await client.channels.fetch(r.channel_id).catch(() => null);
            if (chan) await chan.send({ content: `<@${r.user_id}> ${text}`, allowedMentions: { users: [r.user_id] } }).catch(() => {});
          }
        } catch { /* individual failure */ }
        suiteMarkReminderDone(r.id);
      }
    } catch { /* never fatal */ }
  }, 15000);
  // Keep the timer from holding the process open during --deploy-style runs.
  if (suiteReminderTimer && typeof suiteReminderTimer.unref === 'function') suiteReminderTimer.unref();
}

// ---- suite housekeeping: stale game states + delivered reminders -----------------
function suiteSweepGames() {
  const cutoff = Date.now() - 30 * 60_000; // unplayed games expire after 30 min
  for (const [k, g] of SUITE_GAMES) if (!g.ts || g.ts < cutoff) SUITE_GAMES.delete(k);
  for (const [k, g] of SUITE_GAME_NOUNCES) if (!g.ts || g.ts < cutoff) SUITE_GAME_NOUNCES.delete(k);
}
function suiteGcReminders() {
  try {
    suiteReminderTable();
    sqlite.prepare('DELETE FROM suite_reminders WHERE done = 1 AND due_at < ?').run(Date.now() - 7 * 86400_000);
  } catch { /* never fatal */ }
}

// ---- register the hubs as real commands ---------------------------------------------
const SUITE_TOTAL_ENDPOINTS = suiteEndpointCount();

// Discord hard-caps ONE application command at 8,000 characters of JSON
// (APPLICATION_COMMAND_TOO_LARGE — and one oversized command fails the ENTIRE
// registration, leaving the old command set in place). The text hub is
// 3-13x over that cap when merged, so it registers SPLIT: one top-level
// command per category group (/text-case, …) plus a small
// base command (/text) that keeps the hub-level tools and a `tools`
// index. (The former /math hub was removed in v1.6.0 and the /convert
// hub in v1.7.0 at the owner's request — those commands are gone.)
const SUITE_SPLIT_HUBS = new Set(['text']);
const SUITE_CMD_ROUTES = {}; // commandName -> { hub, group? }
let SUITE_TOP_COMMANDS = 0;

function suiteAddCommand(builder) {
  COMMANDS.push({
    data: builder,
    async execute(interaction) {
      return runSuiteCommand(interaction);
    },
    async autocomplete(interaction) {
      return suiteAutocomplete(interaction);
    },
  });
  SUITE_TOP_COMMANDS += 1;
}

function buildSuiteGroupCommand(hub, g) {
  if (g.tools.length > 25) throw new Error(`Group /${hub.name}-${g.key} has ${g.tools.length} tools (max 25).`);
  const builder = new SlashCommandBuilder()
    .setName(`${hub.name}-${g.key}`)
    .setDescription(truncate(`${g.desc} • ${hub.name} suite`, 100));
  for (const tool of g.tools) {
    builder.addSubcommand(sc => {
      sc.setName(tool.key).setDescription(truncate(tool.desc, 100));
      for (const o of tool.opts || []) {
        const add = SUITE_OPT_BUILDERS[o.type || 'string'];
        if (add) add(sc, o);
      }
      return sc;
    });
  }
  return builder;
}

function buildSuiteSplitBaseCommand(hub) {
  const builder = new SlashCommandBuilder()
    .setName(hub.name)
    .setDescription(truncate(hub.desc, 100));
  for (const sub of hub.subs || []) {
    builder.addSubcommand(sc => {
      sc.setName(sub.key).setDescription(truncate(sub.desc, 100));
      for (const o of sub.opts || []) {
        const add = SUITE_OPT_BUILDERS[o.type || 'string'];
        if (add) add(sc, o);
      }
      return sc;
    });
  }
  builder.addSubcommand(sc => sc.setName('tools')
    .setDescription(truncate(`List every /${hub.name}-… command in this hub`, 100)));
  const topOptions = (hub.subs || []).length + 1;
  if (topOptions > 25) throw new Error(`Hub /${hub.name} has ${topOptions} top-level options (max 25).`);
  return builder;
}

// Synthetic `tools` index subcommand on each split-hub base command — lists
// every command of that hub with live tool counts.
function suiteToolsIndexTool(hubKey) {
  const hub = SUITE_HUBS[hubKey];
  return {
    key: 'tools',
    desc: `List every /${hub.name}-… command`,
    run: () => {
      const lines = [];
      if ((hub.subs || []).length) {
        lines.push(`**/${hub.name}** — ${hub.subs.map(s => s.key).join(' • ')}`);
      }
      for (const g of hub.groups || []) {
        lines.push(`**/${hub.name}-${g.key}** — ${g.desc} *(${g.tools.length} tools)*`);
      }
      return {
        title: `${(typeof HELP_HUB_ICONS !== 'undefined' && HELP_HUB_ICONS[hubKey]) || '🧮'} /${hub.name} — ${helpHubToolCount(hubKey)} tools in ${lines.length} commands`,
        desc: `This hub is split into one command per category (Discord caps a single command at 8,000 characters):\n\n${lines.join('\n')}`,
      };
    },
  };
}

for (const hub of Object.values(SUITE_HUBS)) {
  if (!SUITE_SPLIT_HUBS.has(hub.name)) {
    SUITE_CMD_ROUTES[hub.name] = { hub: hub.name };
    suiteAddCommand(buildSuiteHubCommand(hub));
    continue;
  }
  for (const g of hub.groups || []) {
    SUITE_CMD_ROUTES[`${hub.name}-${g.key}`] = { hub: hub.name, group: g.key };
    suiteAddCommand(buildSuiteGroupCommand(hub, g));
  }
  SUITE_CMD_ROUTES[hub.name] = { hub: hub.name };
  suiteAddCommand(buildSuiteSplitBaseCommand(hub));
}
// >>> SUITE-GLUE-END

// >>> HELP-CENTER-START
// ---------------------------------------------------------------------------
// 13.7 /help — interactive command center. One select menu, 17 category pages.
// Hub pages are generated live from SUITE_HUBS, so tool counts never go stale.
// ---------------------------------------------------------------------------
// --- animated-emoji decoration (the guild's own custom emojis) --------------------
// The owner uploaded custom ANIMATED emojis to the guild — the bot sprinkles
// them across /help and /status automatically. Matching is keyword-first (so
// an uploaded "booststar" lands on the stats header, a "nitroserver" on the
// servers field), then round-robin over whatever animated emojis exist;
// guilds with none keep the classic static icons. Decoration must NEVER be
// able to break a command — every helper is total (never throws).
function guildAnimEmojis(guild) {
  try {
    if (!guild || !guild.emojis || !guild.emojis.cache) return [];
    return [...guild.emojis.cache.values()].filter(e => e && e.animated && e.id && e.name);
  } catch { return []; }
}

function animToken(e) { return `<a:${e.name}:${e.id}>`; }

// Stable order (by snowflake id, numerically) so the same emoji always lands
// on the same spot regardless of the runtime's ICU collation.
function animSorted(guild) {
  return guildAnimEmojis(guild).sort((a, b) => {
    const x = BigInt(a.id), y = BigInt(b.id);
    return x < y ? -1 : x > y ? 1 : 0;
  });
}

// Keyword-scored pick: first animated emoji whose NAME contains one of the
// keywords (lowercase substring). Returns the <a:name:id> token or null.
function pickAnimEmoji(guild, keywords) {
  const list = animSorted(guild);
  if (!list.length) return null;
  const kws = (Array.isArray(keywords) ? keywords : [keywords]).map(k => String(k).toLowerCase());
  for (const kw of kws) {
    const hit = list.find(e => String(e.name).toLowerCase().includes(kw));
    if (hit) return animToken(hit);
  }
  return null;
}

// Round-robin fallback — a DIFFERENT animated emoji per slot so every upload
// gets screen time (node cards, description lines).
function animEmojiAt(guild, i) {
  const list = animSorted(guild);
  if (!list.length) return null;
  return animToken(list[Math.abs(i || 0) % list.length]);
}

// Decoration with static fallback, e.g. animDeco(guild, '📊', ['chart','stats'])
function animDeco(guild, fallback, keywords) {
  return pickAnimEmoji(guild, keywords) || fallback;
}

// Ranked decoration: keyword match first; else the i-th animated emoji
// (round-robin — so titles and field headers are ALWAYS animated when the
// guild has any); else the static fallback.
function animDecoRanked(guild, fallback, keywords, i) {
  const kw = pickAnimEmoji(guild, keywords);
  if (kw) return kw;
  return animEmojiAt(guild, i) || fallback;
}

// Node names are sometimes literally hostnames (e.g. "vitus-node1.devabyss.
// indevs.in"). FQDNs are never supposed to be displayed — show just the short
// label ("vitus-node1") instead. Plain names ("Node 1", "vitus-node1") pass
// through untouched.
function cleanNodeName(n) {
  let raw = String((n && n.name) || '').trim();
  const fq = String((n && n.fqdn) || '').trim();
  const hostLike = (s) => /^[a-z0-9][a-z0-9-]*(\.[a-z0-9-]+)+$/i.test(s) && s.split('.').length >= 2;
  if (fq && raw.toLowerCase() === fq.toLowerCase()) raw = raw.split('.')[0];
  else if (hostLike(raw)) raw = raw.split('.')[0];
  return (raw || `node-${(n && n.id) || '?'}`).slice(0, 40);
}

