function helpStats() {
  const suite = (typeof SUITE_TOTAL_ENDPOINTS === 'number' && SUITE_TOTAL_ENDPOINTS > 0) ? SUITE_TOTAL_ENDPOINTS : 900;
  const suiteCmds = (typeof SUITE_TOP_COMMANDS === 'number' && SUITE_TOP_COMMANDS > 0) ? SUITE_TOP_COMMANDS : 8;
  const commandCount = (typeof COMMANDS !== 'undefined' && Array.isArray(COMMANDS) && COMMANDS.length) ? COMMANDS.length : (27 + suiteCmds);
  const core = commandCount - suiteCmds; // suite commands carry the tools counted above
  return { suite, core: core > 0 ? core : 27, total: (core > 0 ? core : 27) + suite };
}

function helpHubToolCount(hubKey) {
  const hub = SUITE_HUBS[hubKey];
  if (!hub) return 0;
  let n = (hub.subs || []).length;
  for (const g of hub.groups || []) n += g.tools.length;
  return n;
}

function helpSelectOptions(interaction) {
  // Animated emoji assignment — TWO passes so keyword matches are never
  // starved by early options: (1) every option's keyword set claims a matching
  // emoji by NAME; (2) leftover options take any still-unused upload
  // round-robin; (3) options with nothing left keep the static icon. Custom
  // emojis are passed as { id, name, animated } objects — the <a:name:id>
  // STRING form silently drops the id in discord.js and renders broken.
  const pool = animSorted(interaction && interaction.guild);
  const used = new Set();
  const custom = (e) => ({ id: e.id, name: e.name, animated: true });
  const opts = [
    ['home', 'Overview', 'Numbers, quick start & how to browse'],
    ['ai', 'AI & Assistant', '/ai, /ai-reset, /smart + pings & voice triggers'],
    ['servers', 'Servers & Power', 'info, power, /ip, /list players, /plugins'],
    ['extras', 'Files, Backups & Network', '/file /backup /optimize /install /plugins …'],
    ['tickets', 'Tickets', 'panel, create, close, claim, transcript'],
    ['mod', 'Moderation', '/mod, /timeout, /nuke, /lock, /antinuke'],
    ['users', 'Panel Users', '/user create & creds, /admin user'],
    ['embeds', 'Embeds & Presence', '/embed, /react, /vc + auto reactions'],
    ['community', 'Levels & Fun', '/rank /leaderboard /ship /gayness /lesbianess + meters'],
    ['admin', 'Admin & Setup', '/admin, /server-create, /permissions, /settings, /update'],
    ['text', '/text tools', `${helpHubToolCount('text')} text & encoding tools`],
    ['fun', '/fun tools', `${helpHubToolCount('fun')} games & humor tools`],
    ['util', '/util tools', `${helpHubToolCount('util')} info & utility tools`],
    ['time', '/time tools', `${helpHubToolCount('time')} date & time tools`],
    ['color', '/color tools', `${helpHubToolCount('color')} color theory tools`],
    ['mc', '/mc tools', `${helpHubToolCount('mc')} Minecraft tools`],
  ];
  const assigned = new Array(opts.length).fill(null);
  // pass 1 — keyword claims
  opts.forEach(([v], i) => {
    for (const kw of (HELP_ANIM_KEYS[v] || [])) {
      const hit = pool.find(e => !used.has(e.id) && String(e.name).toLowerCase().includes(kw));
      if (hit) { used.add(hit.id); assigned[i] = custom(hit); return; }
    }
  });
  // pass 2 — round-robin fill
  opts.forEach((_, i) => {
    if (assigned[i]) return;
    const next = pool.find(e => !used.has(e.id));
    if (next) { used.add(next.id); assigned[i] = custom(next); }
  });
  return opts.map(([v, l, d], i) => new StringSelectMenuOptionBuilder()
    .setValue(v).setLabel(l).setEmoji(assigned[i] || HELP_FALLBACK_ICONS[v] || '🧩').setDescription(truncate(d, 100)));
}

function helpHomeEmbed(interaction) {
  const s = helpStats();
  const g = interaction && interaction.guild;
  // Modern layout: animated title, quote-block feature list, animated field
  // headers — every line gets one of the guild's uploaded animated emojis
  // (keyword-matched by name, round-robin otherwise).
  const deco = (key) => animDecoRanked(g, HELP_FALLBACK_ICONS[key] || '✨', HELP_ANIM_KEYS[key], HELP_KEY_ORDER.indexOf(key));
  const e = new EmbedBuilder()
    .setColor(COLORS.info)
    .setTitle(`${deco('home')} ${BOT_NAME} — command center`)
    .setDescription(
      `**The all-in-one bot for your Pterodactyl panel.**\n` +
      `> ${deco('servers')} manage servers, power & resources\n` +
      `> ${deco('extras')} files, backups, mods — one-click /optimize\n` +
      `> ${deco('tickets')} tickets with **AI auto-replies**\n` +
      `> ${deco('mod')} moderation + anti-nuke protection\n` +
      `> ${deco('ai')} an AI that answers pings & “noctis help him”\n` +
      `> ${deco('util')} a **${s.suite}-tool** utility suite`
    )
    .addFields(
      { name: `${deco('admin')} By the numbers`, value: `**${s.core}** management commands • **${s.suite}** utility tools • **${s.total}** command endpoints`, inline: false },
      { name: `${deco('community')} Quick start`, value: '`/ai hello there` — chat with the AI\n`/server list` — see your servers\n`/optimize server:<name>` — install performance mods in one click\n`/ip server:<name>` — the address to connect with\n`/server-create` — spawn a new server (wizard)', inline: false },
      { name: `${deco('time')} How to browse`, value: 'Pick a **category** in the menu below — each of the 6 utility hubs has its own page. Or start typing (`/text-`, `/fun`, `/util`…) and Discord lists every option live.', inline: false },
    )
    .setFooter({ text: `${BOT_NAME} v${VERSION} • Pick a category below ⬇️` })
    .setTimestamp();
  try {
    const botUser = interaction && interaction.client && interaction.client.user;
    if (botUser) {
      e.setThumbnail(botUser.displayAvatarURL({ size: 256 }));
      if (botUser.tag) e.setAuthor({ name: botUser.tag });
    }
  } catch { /* avatar unavailable in some contexts */ }
  return e;
}

function helpHubEmbed(hubKey, guild) {
  const hub = SUITE_HUBS[hubKey];
  if (!hub) return embWarn('Unknown hub', 'That utility hub does not exist.');
  const toolCount = helpHubToolCount(hubKey);
  const split = (typeof SUITE_SPLIT_HUBS !== 'undefined' && SUITE_SPLIT_HUBS.has(hubKey));
  const cmdCount = split ? (hub.groups || []).length + 1 : 1;
  const icon = animDecoRanked(guild, HELP_HUB_ICONS[hubKey] || '🧮', HELP_ANIM_KEYS[hubKey], HELP_KEY_ORDER.indexOf(hubKey));
  const e = new EmbedBuilder()
    .setColor(HELP_ACCENTS[hubKey] || COLORS.info)
    .setTitle(`${icon} /${hub.name} — ${toolCount} tools`)
    .setDescription(split
      ? `${HELP_HUB_BLURB[hubKey] || hub.desc}\n\nDiscord caps a single command at **8,000 characters**, so this hub is split into **${cmdCount} commands** — one per category. Type \`/${hub.name}-\` in the picker and they all appear.\n\`/${hub.name} tools\` lists them too.`
      : `${HELP_HUB_BLURB[hubKey] || hub.desc}\n\nType \`/${hub.name}\` and Discord's picker shows every tool — unit, color and timezone options even have autocomplete.`)
    .setFooter({ text: `${BOT_NAME} v${VERSION} • Utility suite • ${toolCount} tools${split ? ` in ${cmdCount} commands` : ` in /${hub.name}`}` })
    .setTimestamp();
  const fields = [];
  for (const g of hub.groups || []) {
    fields.push({
      name: truncate(split ? `/${hub.name}-${g.key}` : g.key, 250),
      value: truncate(`${g.desc} — **${g.tools.length} tools**`, 1000),
      inline: true,
    });
  }
  if ((hub.subs || []).length) {
    fields.push({ name: 'Direct tools', value: truncate(hub.subs.map(t => t.key).join(', '), 1000), inline: false });
  }
  e.addFields(fields.slice(0, 25));
  return e;
}

