// ---------------------------------------------------------------------------
// 14. COMMAND REGISTRATION (auto on boot — or force with: node index.js --deploy)
// ---------------------------------------------------------------------------
const commands = new Collection();
for (const cmd of COMMANDS) {
  commands.set(cmd.data.name, cmd);
}

async function registerSlashCommands(force = false) {
  if (!config.token || !config.clientId) {
    throw new Error('DISCORD_TOKEN / CLIENT_ID missing — cannot register slash commands.');
  }
  const body = COMMANDS.map(c => c.data.toJSON());
  // Local pre-flight: Discord rejects the ENTIRE registration if any single
  // command exceeds 8,000 characters (APPLICATION_COMMAND_TOO_LARGE) — the
  // classic symptom is "Sync failed / Command exceeds maximum size (8000)".
  // Catch it here with a precise list instead of a cryptic API error.
  const oversized = [];
  for (let i = 0; i < body.length; i++) {
    const size = JSON.stringify(body[i]).length;
    if (size > 8000) oversized.push(`/${body[i].name} (${size} chars)`);
  }
  if (oversized.length) {
    throw new Error(`Command(s) exceed Discord's 8,000-character limit: ${oversized.join(', ')} — they must be split into smaller commands.`);
  }
  const hash = crypto.createHash('sha256').update(JSON.stringify(body)).digest('hex');
  // The config key is VERSIONED ("v2"): bumping it forces ONE clean
  // re-registration after updates where a previous PUT failed or Discord's
  // copy went stale (symptom: /help lists commands the picker does not show).
  if (!force && dbGetConfig('commands_hash_v2') === hash) {
    return { skipped: true, count: body.length };
  }
  const rest = new REST({ version: '10' }).setToken(config.token);
  const route = config.guildId
    ? Routes.applicationGuildCommands(config.clientId, config.guildId)
    : Routes.applicationCommands(config.clientId);
  // A failed PUT leaves Discord serving the OLD command set — which looks like
  // "the new commands are missing". Retry with backoff so a transient network
  // blip never strands an outdated command list.
  let lastErr;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const data = await rest.put(route, { body });
      dbSetConfig('commands_hash_v2', hash);
      return { skipped: false, count: Array.isArray(data) ? data.length : 0 };
    } catch (err) {
      lastErr = err;
      if (attempt < 3) await sleep(attempt * 5000);
    }
  }
  throw lastErr;
}

// Live NaraRouter key check — verifies the loaded key against the real
// endpoint at boot, so a bad key shows up in the panel console IMMEDIATELY
// (with a masked fingerprint + fix checklist) instead of as a mysterious
// "Something went wrong" on the first /ai command.  Result is also surfaced
// in /settings view.  aiKeyStatus: null = not checked yet.
let aiKeyStatus = null;
async function checkAiKey() {
  if (!config.aiEnabled || !config.naraApiKey) return;
  try {
    const res = await axios.get(`${config.naraUrl}/models`, {
      headers: { Authorization: `Bearer ${config.naraApiKey}` },
      timeout: 12000,
      validateStatus: () => true,
    });
    if (res.status < 400) {
      const n = res.data && Array.isArray(res.data.data) ? res.data.data.length : null;
      aiKeyStatus = { ok: true, status: res.status, detail: n !== null ? `${n} models available` : 'endpoint reachable', checkedAt: new Date() };
      console.log(`[ai] NaraRouter key verified ✓ ${maskKey(config.naraApiKey)} — ${aiKeyStatus.detail} (${config.naraUrl})`);
    } else {
      const detail = res.data && res.data.error && res.data.error.message ? ` — ${truncate(String(res.data.error.message), 120)}` : '';
      aiKeyStatus = { ok: false, status: res.status, detail: `HTTP ${res.status}${detail}`, checkedAt: new Date() };
      console.warn('='.repeat(62));
      console.warn(`[ai] ⚠ NaraRouter REJECTED the API key (HTTP ${res.status}${detail}).`);
      console.warn('[ai]   AI commands (/ai, /smart, ticket AI) will fail until this is fixed.');
      console.warn(`[ai]   key loaded by the bot: ${maskKey(config.naraApiKey)} • endpoint: ${config.naraUrl}`);
      console.warn('[ai]   fix: copy the FULL key from the NaraRouter dashboard into NARA_API_KEY=');
      console.warn('[ai]        (ONE line, no quotes/spaces) in .env, then RESTART the bot.');
      console.warn('='.repeat(62));
    }
  } catch (err) {
    aiKeyStatus = { ok: false, status: 0, detail: truncate(err.code || err.message, 120), checkedAt: new Date() };
    console.warn(`[ai] Could not verify the NaraRouter key (${aiKeyStatus.detail}) — will retry on the first AI command.`);
  }
}

